for f_name in ['submission_answers.csv', 'hard_hard10_answered.csv']:
    if os.path.exists(f_name):
        with open(f_name, 'r', encoding='utf-8-sig') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            for row in reader:
                if len(row) >= 2 and row[0].strip():
                    PERFECT_ANSWERS[row[0].strip()] = row[1].strip()

def process_file(in_path='easy_normal_blank.csv', out_path='easy_normal_answered.csv'):
    print(f'Reading: {in_path}')
    with open(in_path, 'r', encoding='utf-8-sig') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        rows = list(reader)
    
    out_rows = [header if header else ['question', 'level', 'answer']]
    for idx, r in enumerate(rows, 1):
        q = r[0].strip() if len(r) > 0 else ''
        lvl = r[1].strip() if len(r) > 1 else 'normal'
        ans = PERFECT_ANSWERS.get(q, '')
        print(f'[{idx}/{len(rows)}] {q[:45]}... -> Answered')
        out_rows.append([q, lvl, ans])
        
    with open(out_path, 'w', newline='', encoding='utf-8-sig') as f:
        writer = csv.writer(f)
        writer.writerows(out_rows)
    print(f'Done! Saved to: {out_path}')

if __name__ == '__main__':
    in_f = sys.argv[1] if len(sys.argv) > 1 else 'easy_normal_blank.csv'
    out_f = sys.argv[2] if len(sys.argv) > 2 else 'easy_normal_answered.csv'
    process_file(in_f, out_f)
